import XCTest

final class PhoenixUITests: XCTestCase {
    func testOpenProjectPhoenixMembers() throws {
        let base = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/uitest/"
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let room = app.staticTexts["Project Phoenix"].firstMatch
        XCTAssertTrue(room.waitForExistence(timeout: 15), "Project Phoenix room not found")
        if !app.navigationBars["Project Phoenix"].exists {
            room.tap()
        }
        sleep(2)

        let title = app.navigationBars["Project Phoenix"].staticTexts["Project Phoenix"].firstMatch
        if title.waitForExistence(timeout: 5) {
            title.tap()
        }
        sleep(3)

        try XCUIScreen.main.screenshot().pngRepresentation.write(to: URL(fileURLWithPath: base + "details.png"))
        try app.debugDescription.write(toFile: base + "details_tree.txt", atomically: true, encoding: .utf8)

        let people = app.staticTexts["People"].firstMatch
        let peopleButton = app.buttons["People"].firstMatch
        if peopleButton.waitForExistence(timeout: 3) {
            peopleButton.tap()
        } else if people.waitForExistence(timeout: 2) {
            people.tap()
        }
        sleep(3)

        try XCUIScreen.main.screenshot().pngRepresentation.write(to: URL(fileURLWithPath: base + "people.png"))
        try app.debugDescription.write(toFile: base + "people_tree.txt", atomically: true, encoding: .utf8)
    }
}

